"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def N_QUEENS(N):
    board = []
    for i in range(0, N):
        board[i] = []
        for j in range(0, N):
            board[i][j] = 0
    def IS_SAFE(row, col):
        for i in range(0, row):
            if (board[i][col] == 1):
                return False
            if (((col - (row - i)) >= 0) and (board[i][(col - (row - i))] == 1)):
                return False
            if (((col + (row - i)) < N) and (board[i][(col + (row - i))] == 1)):
                return False
        return True
    def PLACE_QUEENS(row):
        if (row == N):
            return True
        for col in range(0, N):
            if IS_SAFE(row, col):
                board[row][col] = 1
                if PLACE_QUEENS((row + 1)):
                    return True
                board[row][col] = 0
        return False
    if PLACE_QUEENS(0):
        return board
    else:
        return None

print(N_QUEENS(4))